svg.script:
var token_glass = {
  menu: {
    'Value +1': {
      eventName: 'value_incr_1',
      otherEvents: ['dblclick'],
      applicable: (node) => { return true },
      handler: function(evt) {
        token_glass.increment(this, 1)
      },
    },
  },

  increment: function(elem, num) {
    let firstGI = elem.querySelector('.game-icon')
    let vis = elem.querySelector('.game-icon:not([display="none"])')
    if (!vis) {
      firstGI.setAttribute('display', '')
      return
    }
    let nextSibling = vis.nextElementSibling;
    vis.setAttribute('display', 'none')
    if (nextSibling) {
      nextSibling.setAttribute('display', '')
    }
  },

  // value comes from the Tools panel's range slider (0-24) when placing a
  // fresh token; absent on clone, where the cloned face is kept as-is.
  // 0 is the null case: every .game-icon hidden, same state increment()
  // leaves you in after cycling past the last face.
  initialize: function(elem, value) {
    if (typeof value !== 'number' || !Number.isFinite(value)) return
    elem.querySelectorAll('.game-icon').forEach(icon => {
      const idx = Number(icon.getAttribute('data-token-style-index'))
      icon.setAttribute('display', idx === value ? '' : 'none')
    })
  },

}
